from typing import List

def order_by_points(nums: List[int]) -> List[int]:
    """
    Sort the given list of integers in ascending order according to the sum of their
    digits. If several items have the same digit sum, their relative order from the
    original list is preserved.
    """
    def digit_sum(n: int) -> int:
        return sum(int(d) for d in str(abs(n)))

    return sorted(nums, key=digit_sum)
